using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;

namespace ModelBindingValidation.Models
{
    public class EventRegistration : IValidatableObject
    {
        [Required]
        public string EventName { get; set; }

        [Required]
        public DateTime StartDate { get; set; }

        [Required]
        public DateTime EndDate { get; set; }

        public IEnumerable<ValidationResult> Validate(ValidationContext context)
        {
            if (EndDate < StartDate)
            {
                yield return new ValidationResult(
                    "End date must be on or after the start date.",
                    new[] { nameof(EndDate) });
            }
            if ((EndDate - StartDate).TotalDays > 30)
            {
                yield return new ValidationResult(
                    "Event duration cannot exceed 30 days.",
                    new[] { nameof(EndDate) });
            }
        }
    }
}

using Microsoft.AspNetCore.Mvc;

namespace ModelBindingValidation.Controllers
{
    public class AccountController : Controller
    {
        // GET: /Account/CheckUsername?username=john
        public JsonResult CheckUsername(string username)
        {
            var taken = username.ToLower() is "admin" or "root" or "superuser";
            return taken
                ? Json("This username is already taken.")
                : Json(true);
        }
    }
}

